describe('Optimistic UI Updates for Liking a Post', () => {
    const postId = '12345';

    beforeEach(() => {
        cy.intercept('POST', `/api/posts/${postId}/like`, {
            statusCode: 200,
            body: { success: true, likes: 1 },
        }).as('likePost');

        cy.visit('/posts');
    });

    it('should optimistically update the like count when the like button is clicked', () => {
        cy.get(`[data-testid="post-${postId}"]`).within(() => {
            cy.get('[data-testid="like-button"]').click();
            cy.get('[data-testid="like-count"]').should('contain', '1');
        });

        cy.wait('@likePost').its('response.statusCode').should('eq', 200);
    });

    it('should handle like failure gracefully', () => {
        cy.intercept('POST', `/api/posts/${postId}/like`, {
            statusCode: 500,
            body: { success: false, message: 'Internal Server Error' },
        }).as('likePostFail');

        cy.get(`[data-testid="post-${postId}"]`).within(() => {
            cy.get('[data-testid="like-button"]').click();
            cy.get('[data-testid="like-count"]').should('contain', '1');
        });

        cy.wait('@likePostFail');

        cy.get(`[data-testid="post-${postId}"]`).within(() => {
            cy.get('[data-testid="error-message"]').should('be.visible').and('contain', 'Internal Server Error');
            cy.get('[data-testid="like-count"]').should('contain', '0');
        });
    });
});
